import numpy as np
import matplotlib.pyplot as plt
import tskit
import tszip
from scipy.stats import hmean

demo_names = ["const", "exp", "split_500", "split_1000", "split_2000","out_of_africa","bottleneck_2000","step_05","step_005","step_0005"]

def getCoalConst(N, t):
    return 1.0 / (2 * N)

def getCoalBottleneck(N_recent, N_ancestral, t_change, t):
    if t < t_change:
        N = N_recent
    else:
        N = N_ancestral
    return 1.0 / (2 * N)

def getCoalExp(startN, growth_rate, startExp, t):
    if t < startExp:
        N = startN * np.exp(-growth_rate * t)
    else:
        N = startN * np.exp(-growth_rate * startExp)   
    return 1.0 / (2 * N)

def getCoalSplit(splitN, beforeN, splitTime, t, popComparison):
    if popComparison in [(0,1), (1,0)]:
        if t < splitTime:
            return 0
        if t >= splitTime:
            return 1/(2 * beforeN)
    else:
        if t < splitTime:
            return 1/(2*splitN)
        if t >= splitTime:
            return 1/(2 * beforeN)
   
def getCoal(demo_name, t, popComparison):
    if demo_name == "bottleneck_2000":
        return getCoalBottleneck(5000,10000,2000,t)
    if demo_name == "exp":
        return getCoalExp(10000, np.log(4)/250, 250, t)
    if demo_name == "const":
        return getCoalConst(10000,t)
    if demo_name == "split_500":
        return getCoalSplit(5000,10000,500,t,popComparison)
    if demo_name == "split_1000":
        return getCoalSplit(5000,10000,1000,t,popComparison)
    if demo_name == "split_2000":
        return getCoalSplit(5000,10000,2000,t,popComparison)
    
def getReconstructedMeansPopComparison(popIndexes, demo_name, time_intervals):
    props_list = []
    rate_list = []
    counts_list = []
    for j in range(0,50):
        ts = tszip.decompress(f"official_data2/results_np/{demo_name}/trees/{demo_name}.{j}.tsz")
        #make list of populations 
        pops = [None, None]  # reset every iteration
        for pop in ts.populations():
            metadata = pop.metadata
            #switch to YRI, CEU, CHB for out of africa, and deme indexing for stepping stone
            if metadata and "name" in metadata:
                if metadata['name'] == 'DpopA':
                    pops[0] = pop
                elif metadata['name'] == 'DpopB':
                    pops[1] = pop
                    
        #assert pops[0] is not None and pops[1] is not None            
        if None in pops:
            print(f"warning: missing population in tree {j}, skipping")
            continue
        raw_sample_sets = [list(ts.samples(population=pop.id)) for pop in pops]
        #remove empty populations from list or else its weird
        sample_sets = [s for s in raw_sample_sets if len(s) > 0]
        reconstruction_rate  = ts.pair_coalescence_rates(time_windows=time_intervals, 
                                          sample_sets = sample_sets, 
                                          indexes=popIndexes)
        count = ts.pair_coalescence_counts(time_windows=time_intervals, sample_sets = sample_sets, indexes=popIndexes, pair_normalise=False)
        counts_list.append(count[0])
        reconstruction_props = count[0]/count[0].sum() 
        #switch out index depending on which comparison you want to make
        props_list.append(reconstruction_props)
        assert len(reconstruction_props) == len(time_intervals) - 1
        rate_list.append(reconstruction_rate[0])
        
    reconstruction_mean_props = np.mean(props_list, axis=0)
    reconstruction_mean_counts = np.mean(counts_list, axis=0)
    rate_array = np.array(rate_list)
    reconstruction_mean_rate = hmean(rate_array, axis=0)
    return (reconstruction_mean_counts, reconstruction_mean_props, reconstruction_mean_rate)

def getReconstructedMeansDefault(demo_name, time_intervals):
    props_list = []
    rate_list = []
    counts_list = []
    for j in range(0,50):
        ts = tszip.decompress(f"official_data2/results_np/{demo_names[i]}/trees/{demo_names[i]}.{j}.tsz")
        count = ts.pair_coalescence_counts(time_windows=time_intervals, pair_normalise=False)
        reconstruction_props = count/count.sum() 
        reconstruction_rate = ts.pair_coalescence_rates(time_windows=time_intervals)
        counts_list.append(count)
        props_list.append(reconstruction_props)
        rate_list.append(reconstruction_rate)
    reconstruction_mean_props = np.mean(props_list, axis=0)
    reconstruction_mean_counts = np.mean(counts_list, axis=0)
    rate_array = np.array(rate_list)
    reconstruction_mean_rate = hmean(rate_array, axis=0)
    return (reconstruction_mean_counts, reconstruction_mean_props, reconstruction_mean_rate)

def getDefault(ts, time_intervals):
    counts = ts.pair_coalescence_counts(time_windows=time_intervals, pair_normalise=False)
    proportions = counts/counts.sum() 
    rates = ts.pair_coalescence_rates(time_windows=time_intervals)
    return (counts, proportions, rates)

def getPopComparison(popIndexes, ts, time_intervals):
    pops = [None, None]
    for pop in ts.populations():
            metadata = pop.metadata
            if metadata and "name" in metadata:
                if metadata['name'] == 'popA':
                    pops[0] = pop
                elif metadata['name'] == 'popB':
                    pops[1] = pop
    #make list of list of samples 
    if None in pops:
        print(f"warning: missing population...")
        return (None,None,None)
    sample_sets = [list(ts.samples(population=pop.id)) for pop in pops]
    counts = ts.pair_coalescence_counts(time_windows=time_intervals, sample_sets = sample_sets, indexes=popIndexes,  pair_normalise=False)[0]
    proportions = counts/counts.sum()
    rates = ts.pair_coalescence_rates(time_windows=time_intervals, sample_sets = sample_sets, indexes=popIndexes)[0]
    return (counts, proportions, rates)
    

for i in range(2,5):
    index_list = [(0,0),(0,1),(1,1),(1,0)]

    #decompress official sim 
    mutated = tszip.decompress(f"official_data2/diploid_sim/trees/{demo_names[i]}.trees.tsz")
    max_time = mutated.max_time 
    time_intervals = np.logspace(0, np.log10(max_time), 20)
    time_intervals = np.concatenate(([0], time_intervals, [np.inf]))
    plot_intervals = time_intervals.copy()
    plot_intervals[-1] = plot_intervals[-2] * (plot_intervals[-2] / plot_intervals[-3])
    eval_times = plot_intervals[1:-1]

    for k in range(0,4):
        index = [index_list[k]]

        (reconstruction_mean_counts, reconstruction_mean_props, reconstruction_mean_rate) = getReconstructedMeansPopComparison(index, demo_names[i], time_intervals)
        (counts, props, rate) = getPopComparison(index, mutated, time_intervals)
        
       
    
        fig, ax = plt.subplots(figsize=(8, 5))
        ax.stairs(props[1:], plot_intervals[1:], color="blue", linewidth=1.5, label="Truth")
        ax.stairs(reconstruction_mean_props[1:], plot_intervals[1:], color="red", linewidth=1.5, label="SINGER reconstruction")
        ax.set_xscale("log")
        ax.set_xlabel("Generations in past")
        ax.set_ylabel("Proportion coalescing pairs")
        ax.legend()
        plt.title(f"Ground truth + SINGER reconstruction proportion coalescing pairs over time, population comparison {index[0]}, no Polegon \n Demographic model: {demo_names[i]}")
        plt.tight_layout()
        plt.savefig(f"official_data2/plots_np/{demo_names[i]}_props{index[0]}_np.pdf", dpi=300, bbox_inches="tight")
        #plt.show()
    
        #analytic_demos = {"const", "exp", "bottleneck_2000"}
        analytic_demos = {"const", "exp", "bottleneck_2000", "split_500", "split_1000", "split_2000"}
        
        fig, ax = plt.subplots(figsize=(8, 5))
        ax.stairs(rate[1:-1], plot_intervals[1:-1], color="blue", linewidth=1.5, label = "Truth")
        ax.stairs(reconstruction_mean_rate[1:-1], plot_intervals[1:-1], color="red", linewidth=1.5, label = "SINGER reconstruction")
        if demo_names[i] in analytic_demos:
            empirical_rates = [getCoal(demo_names[i], t, index[0]) if t <= max_time else np.nan for t in eval_times]
            ax.stairs(empirical_rates, plot_intervals[1:], color="black", linewidth=1.5,
                  linestyle="--", label="Empirical Ne(t)")
        ax.set_xscale("log")
        ax.set_xlabel("Generations in past")
        ax.set_ylabel("Pair coalescent rates")
        ax.legend()
        plt.title(f"Ground truth + SINGER reconstruction coalescent rates over time, population comparison {index[0]}, no Polegon \n Demographic model: {demo_names[i]}")
        plt.tight_layout()
        plt.savefig(f"official_data2/plots_np/{demo_names[i]}_rates{index[0]}_np.pdf", dpi=300, bbox_inches="tight")
        #plt.show()
    
        fig, ax = plt.subplots(figsize=(8, 5))
        ax.stairs(counts[1:], plot_intervals[1:], color="blue", linewidth=1.5, label = "Truth")
        ax.stairs(reconstruction_mean_counts[1:], plot_intervals[1:], color="red", linewidth=1.5, label = "SINGER reconstruction")
        ax.set_xscale("log")
        ax.set_xlabel("Generations in past")
        ax.set_ylabel("Number coalescing pairs")
        ax.legend()
        plt.title(f"Ground truth + SINGER reconstruction number of coalescing pairs over time, population comparison {index[0]}, no Polegon \n Demographic model: {demo_names[i]}")
        plt.tight_layout()
        plt.savefig(f"official_data2/plots_np/{demo_names[i]}_counts{index[0]}_np.pdf", dpi=300, bbox_inches="tight")
